from pathlib import Path
import json,html,csv
D=Path(__file__).parent;Q=D/'audit';read=lambda n:json.loads((Q/n).read_text(encoding='utf8'));E=lambda x:html.escape(str(x));fmt=lambda v:f'{v:,.6f}'
suites=[]
for name,label in [('features-engine-qa.json','Leader decisions and 144 additional-budget combinations'),('features-browser-qa.json','New ExCo controls and two-way synchronization'),('topup-oracle-qa.json','Independent workbook replay of additional funding'),('browser-qa.json','32 scenarios across all six tabs and extract filters'),('regression-browser-qa.json','Existing browser and recovery workflows'),('refresh-ui-qa.json','Changed-source refresh and recommendation guard'),('oracle-qa.json','Independent source replay of 32 baseline scenarios'),('export-qa.json','32 downloaded Excel workbooks')]:
 raw=read(name);cs=raw['checks'];passed=sum(bool(x.get('passed',x.get('status')=='PASS')) for x in cs);suites.append({'file':name,'label':label,'checks':len(cs),'passed':passed,'fatal':raw.get('fatal')})
total=sum(x['checks'] for x in suites);passed=sum(x['passed'] for x in suites);tests=read('features-engine-qa.json')['topupCases'];browser=read('topup-browser-result.json');r=browser['result'];base=read('scenarios.json')['scenarios'][0]['result'];before={x['id']:x for x in base['rows']};changes=[x for x in r['rows'] if abs(x['final']-before[x['id']]['final'])>1e-8]
requirements=[('EXCO59-01','Leader decisions','Expose inclusion, exclusion, automatic funding, partial scope, request and merit review for all base Programs priorities. Keep PMI separate. Preview changes with rationale; persist through the shared scenario transaction.'),('EXCO59-02','Company controls','Expose budget, tolerance, merit floor, five score weights, four editable lever bases/amounts and optional IT Simplification. Label these settings company-wide and preview before apply.'),('EXCO59-03','Decision chart','Toggle requested Demand and quantified Hard Benefits against merit. Use log(1 + amount), request-scaled bubbles and funding status. Support mouse and keyboard source detail access.'),('EXCO59-04','Additional funding','Accept a positive additional company envelope, one leader, optional stream and rationale. Select eligible whole remaining scopes in priority-stage then merit order. Respect confirmed carry caps and explicit manual exclusions. Preview additions, budget, headroom and recipient costs.'),('EXCO59-05','Retained allocations','Keep existing funding unchanged when applying additional funding. Record retained automatic decisions as explicit overrides. Allow previewed return of these retained decisions to automatic; undo restores the whole additional-funding transaction.'),('EXCO59-06','Benefit evidence','Separate newly funded productivity, revenue and soft lifetime claims. Label productivity as a savings proxy. Do not infer annual savings, realised returns or incremental benefits for already funded partial scopes.'),('EXCO59-07','Custom columns','Offer normalized scenario fields and original EW/BU source columns. Keep Programs ID/name/source access mandatory. Save column choices per leader in the scenario; retain them through save/reload, portable export and fork.'),('EXCO59-08','Synchronized selection','Synchronize ExCo leader selections with the Programs filters in tabs 2–4 and One Portfolio. Support multiple leaders selected in the workbench. All six views and exports use the same funding and finance result; Operations recipient costs remain company-wide.'),('EXCO59-09','State and validation','Guard decision previews against a changed scenario ID, revision or source hash. Lock edits on finalised scenarios. Preserve earlier HTML builds and both source workbooks; validate source-linked Programs and recipient ledgers.')]
(D/'requirements.json').write_text(json.dumps(requirements,indent=2,ensure_ascii=False),encoding='utf8')
style='body{font:16px Calibri,Arial;color:#143052;background:#f5f8fc;margin:0}header{padding:30px 5%;background:#0b5ed7;color:white}main{max-width:1400px;margin:auto;padding:20px}section{background:white;border:1px solid #d5deeb;border-radius:8px;padding:24px;margin:20px 0}h2{color:#00126e}p,li{line-height:1.55}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px;border-bottom:1px solid #dbe3ef;text-align:left;vertical-align:top}th{background:#edf4ff}.scroll{overflow:auto}.kpis{display:flex;gap:16px;flex-wrap:wrap}.kpis div{background:#eef5ff;padding:20px;flex:1}.kpis b{display:block;font-size:28px;color:#00126e}a{color:#075bd8}code{overflow-wrap:anywhere}'
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+E(v)+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def page(title,body):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+style+'</style><header><p>AOP 2027 · v5.9.0 · 30 September 2026</p><h1>'+title+'</h1></header><main>'+body+'</main></html>'
intro='''<section><h2>What changed</h2><p>The ExCo view now supports leader-specific Programs decisions, a Demand / Hard Benefits chart toggle, additional funding previews and custom columns from normalized and original source data. It shares the same scenario as the six-tab workbench. v5.7.0, v5.8.0 and both source workbooks are preserved.</p><ol><li><b>Decisions:</b> select an ExCo leader, adjust inclusion or review request, merit and funded scope. Use Company funding settings for the same budget, levers and scoring configuration available in tab 2.</li><li><b>Funding opportunities:</b> enter an additional budget and rationale, choose both streams or F&R/BU Led, preview the added Programs and recipient costs, then apply or cancel.</li><li><b>Customize columns:</b> search and select scenario or original EW/BU source fields. Choices are stored per leader in the saved scenario. Fork and portable scenario recovery retain them.</li><li><b>Synchronization:</b> edits made in ExCo appear in the workbench, and workbench edits appear in ExCo. ExCo leader filters synchronize across Programs views. Charts and leader filters do not independently change funding.</li></ol><p><a href="AOP2027-IT-Portfolio-Scenario-Modelling-v5.9.0.html">Open v5.9.0</a> · <a href="AOP2027-Modeler-PRD-v5.9.0-ExCo-Addendum.docx">PRD addendum</a> · <a href="AOP2027-Modeler-Detailed-Requirements-v5.9.0-ExCo-Addendum.docx">Requirements addendum</a></p></section>'''
body=intro+f'<section><h2>Validation outcome</h2><div class="kpis"><div><b>{passed}/{total}</b>assertions passed</div><div><b>32</b>existing end-to-end scenarios</div><div><b>144</b>leader / stream / extra-budget combinations</div><div><b>{len(tests)}</b>combinations with eligible additions</div></div><p>The remaining {144-len(tests)} additional-budget combinations correctly reject an empty funding plan. Existing funding and finance calculations match v5.8.0 across all 32 baseline scenarios. Independent source replay validates 69,280 baseline fields and each feasible additional-funding selection and recipient total. The count is a test outcome score, not a measure of financial certainty.</p>'+table(['Suite','Passed','Assertions','Evidence'],[[E(x['label']),x['passed'],x['checks'],f'<a href="audit/{x["file"]}">{x["file"]}</a>'] for x in suites])+'</section>'
body+='<section><h2>Verified additional-funding example</h2><p>This QA example allocates an extra €5M company envelope to Deeptha Khanna across both streams. It is a tested example, not an applied decision in the delivered default scenario.</p>'+table(['Measure','Before M€','After M€','Change M€'],[['Base envelope',fmt(100),fmt(browser['session']['settings']['budget']),fmt(browser['session']['settings']['budget']-100)],['Funded base Programs',fmt(base['totals']['allocation']),fmt(r['totals']['allocation']),fmt(r['totals']['allocation']-base['totals']['allocation'])],['Total IT',fmt(base['finance']['totals']['total']),fmt(r['finance']['totals']['total']),fmt(r['finance']['totals']['total']-base['finance']['totals']['total'])]])
body+=table(['Programs / source','Priority','Merit','Before funded M€','After funded M€','Lifetime benefit claim M€'],[[E(x['id'])+' · '+E(x['sourceSheet'])+' row '+str(x['sourceRow']),E(x['stageName']),x['score'],fmt(before[x['id']]['final']),fmt(x['final']),fmt(x['benefit']) if x['benefit'] is not None else 'Not quantified'] for x in changes])
body+='<p><a href="audit/topup-export.xlsx">Download the tested example evidence workbook</a>. The default delivered build still opens at €100M, funding €99.963M base Programs and €575.467463M total IT.</p></section>'
body+='''<section><h2>Calculation and decision boundaries</h2><p>Additional funding uses the current scenario request, reviewed merit, source eligibility and confirmed carry caps. It sorts eligible remaining scopes by priority stage, descending merit, ascending request and ID. It skips scopes that do not fit the entered extra budget. The company envelope increases by the entered amount; unused extra remains headroom.</p><p>Applying a top-up retains prior funding amounts across the company. This prevents a higher global budget from silently refilling other portfolios. Those retained automatic decisions are visible overrides. Use the return-to-automatic preview to release them, or Undo to restore the entire previous decision. New manual decisions and source refresh rules continue to apply.</p><p>Productivity claims are a savings proxy, shown separately from revenue and soft claims. All remain submitted lifetime claims. The model does not convert them into annual cash savings or assume an incremental benefit when an already funded scope receives more funding. Source benefit evidence stays eligible for prioritization.</p><p>Company settings affect all leaders. Leader and chart filters affect the displayed Programs, while receiving-organisation costs include the full company. Operations remains source-fixed. The approved EW unallocated share of 22.6303317536%, other BU unallocated balances and PMI treatment are unchanged.</p></section>'''
body+='<section><h2>Product requirements and acceptance</h2>'+table(['ID','Capability','Requirement'],[[a,b,E(c)] for a,b,c in requirements])+'</section>'
body+='''<section><h2>Limits and traceability</h2><p>The model remains an offline scenario tool. Finalised is a local editing lock, not a centrally authenticated approval. Saved custom layouts belong to the scenario and carry into its fork; a fresh scenario starts with default layouts. There is no new quantified delivery-capacity or dependency solver. Desktop Chrome was tested at 1366px and 1920px; other browsers and mobile workflows are outside this suite.</p><p>Original source columns retain their source units. All finance and funding computations continue in M€. Source workbook hashes, protected build hashes, source-linked exports and the publication receipt are retained in the release evidence folder.</p><p>The suite corrected two harness assumptions during validation: saved-view checks now wait for persisted state to load, and numeric input comparisons use numeric values. A final UI transition check is recorded in the browser evidence.</p></section>'''
(D/'ExCo-QA-report-v5.9.0.html').write_text(page('ExCo decisions customization and validation',body),encoding='utf8')
(D/'ExCo-PRD-and-Requirements-v5.9.0.html').write_text(page('ExCo decision workspace requirements',intro+'<section><h2>Acceptance contract</h2>'+table(['ID','Capability','Requirement'],[[a,b,E(c)] for a,b,c in requirements])+'</section>'),encoding='utf8')
with (D/'Additional-funding-scenarios.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['Leader','Stream','Additional envelope M€','Added funding M€','Unused extra M€','Programs added']);w.writeheader();w.writerows({'Leader':x['leader'],'Stream':x['stream'],'Additional envelope M€':x['extra'],'Added funding M€':x['spent'],'Unused extra M€':x['remaining'],'Programs added':'; '.join(a['id'] for a in x['additions'])} for x in tests)
(Q/'validation-summary.json').write_text(json.dumps({'version':'5.9.0','assertions':total,'passed':passed,'suites':suites,'baselineScenarios':32,'additionalFundingCombinations':144,'feasibleAdditionalCombinations':len(tests)},indent=2),encoding='utf8');print(json.dumps({'checks':total,'passed':passed,'feasible':len(tests)}))
